const SOURCE='https://alienint.com/types-of-aliens/';
const seeds=[
['Greys','greys','Large-eyed, small-bodied figures associated with clinical encounters in abduction narratives.'],
['Nordics','nordics','Humanlike blond visitors offering guidance in contactee stories.'],
['Reptilians','reptilians','Scaled humanoids associated with concealed power in conspiracy mythology.'],
['Pleiadians','pleiadians','Pleiades-linked humanlike mentors in spiritual contact traditions.'],
['Mantis / Insectoids','insectoids','Insectlike figures portrayed as overseers or healers in encounter accounts.'],
['Little Green Men','little-green-men','Small green figures popularized through entertainment and alien-themed imagery.'],
['Tall Whites','tall-whites','Pale, elongated visitors central to Charles Hall’s Nevada accounts.'],
['Hybrids','hybrids','Human-alien combinations appearing in reproductive themes within abduction literature.'],
['Arcturians','arcturians','Arcturus-associated guides linked with healing in spiritual narratives.'],
['Sirians','sirians','Sirius-linked beings connected with water and ancient wisdom in esoteric lore.'],
['Anunnaki','anunnaki','Mesopotamian deities reinterpreted as extraterrestrials by modern ancient-astronaut writers.'],
['Lyrans','lyrans','Feline-featured ancestral beings associated with Lyra in starseed traditions.']
].map(([name,id,summary],i)=>({id,name,summary,image:SOURCE+id+'.webp',source:SOURCE,kind:'source',number:i+1,status:'Folklore / unverified claims'}));
const KEY='known-aliens-archive-v1';let state={entries:[],overrides:{},saved:[]},filter='all',editing=null,active=null;
const $=s=>document.querySelector(s);const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeURL(value,image=false){if(!value)return '';if(image&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value))return value;try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
const fields=['name','summary','notes','source','image','appearance','origin','behavior','encounters','related','status'];
function clean(e){const out={};for(const k of fields)out[k]=typeof e[k]==='string'?e[k].slice(0,k==='image'?1500000:10000):'';out.source=safeURL(out.source);out.image=safeURL(out.image,true);return out}
function validate(raw,checkNames=true){if(!raw||!Array.isArray(raw.entries)||!Array.isArray(raw.saved)||!raw.overrides||typeof raw.overrides!=='object')throw Error('Invalid archive format');if(raw.entries.length>200)throw Error('Maximum 200 custom entries');const ids=new Set(seeds.map(e=>e.id));const entries=raw.entries.map(e=>{if(!e||typeof e.id!=='string'||!e.id.startsWith('custom-')||ids.has(e.id)||!e.name?.trim()||!e.summary?.trim())throw Error('Invalid or duplicate entry');ids.add(e.id);return {...clean(e),id:e.id,kind:'custom'}});const overrides={};for(const seed of seeds)if(raw.overrides[seed.id])overrides[seed.id]=clean(raw.overrides[seed.id]);if(checkNames)assertUniqueSpecies([...seeds.map(e=>({...e,...overrides[e.id]})),...entries]);return {entries,overrides,saved:[...new Set(raw.saved.filter(id=>ids.has(id)))]}}
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw),false)}catch{setTimeout(()=>toast('Saved data could not be read. Import a backup to restore it.'),100)}
function all(){return [...seeds.map(e=>({...e,...state.overrides[e.id]})),...state.entries]}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true}catch{toast('Could not save: browser storage may be full or disabled. Export a backup.');return false}}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
function bindImages(root){root.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.nextElementSibling.hidden=false},{once:true}))}
function portrait(e){return `<img src="${esc(safeURL(e.image,true))}" alt="Illustration of ${esc(e.name)}" loading="lazy" ${e.image?'':'hidden'}><div class="fallback" ${e.image?'hidden':''}>◎<small>NO PORTRAIT AVAILABLE</small></div>`}
function render(){let items=all();const q=$('#search').value.toLowerCase().trim();items=items.filter(e=>(filter==='all'||filter===e.kind||(filter==='saved'&&state.saved.includes(e.id)))&&(fields.some(k=>String(e[k]||'').toLowerCase().includes(q))||JSON.stringify(RESEARCH[e.id]||{}).toLowerCase().includes(q)));const sort=$('#sort').value;if(sort!=='archive')items.sort((a,b)=>a.name.localeCompare(b.name)*(sort==='az'?1:-1));$('#total').textContent=all().length;$('#count').textContent=`${items.length} ${items.length===1?'entry':'entries'}`;$('#empty').hidden=!!items.length;$('#grid').innerHTML=items.map(e=>`<article class="card"><button class="bookmark ${state.saved.includes(e.id)?'selected':''}" data-save="${esc(e.id)}" aria-label="Bookmark ${esc(e.name)}" aria-pressed="${state.saved.includes(e.id)}">${state.saved.includes(e.id)?'★':'☆'}</button><button class="card-open" data-open="${esc(e.id)}"><div class="portrait"><span class="serial">KA / ${String(e.number||'NEW').padStart(3,'0')}</span>${portrait(e)}</div><div class="card-content"><div class="eyebrow">${e.kind==='source'?'ALIENINT COLLECTION':'PERSONAL COLLECTION'}</div><h3>${esc(e.name)}</h3><p>${esc(e.summary)}</p><div class="card-bottom"><span>Explore entry</span><span>↗</span></div></div></button></article>`).join('');bindImages($('#grid'))}
$('#grid').addEventListener('click',ev=>{const save=ev.target.closest('[data-save]');if(save){const id=save.dataset.save;const saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];if(persist({...state,saved}))render();return}const open=ev.target.closest('[data-open]');if(open)detail(open.dataset.open)});
function nameKey(name){return String(name||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'')}
function assertUniqueSpecies(entries){const owners=new Map();for(const seed of seeds){for(const name of [seed.name,...(RESEARCH[seed.id]?.aliases||[])])owners.set(nameKey(name),seed.id)}for(const e of entries){const key=nameKey(e.name);const owner=owners.get(key);if(owner&&owner!==e.id)throw Error('Duplicate species or known alias: '+e.name);owners.set(key,e.id)}}
function referenceKey(url){try{const u=new URL(url);u.hash='';u.hostname=u.hostname.replace(/^www\./,'');for(const k of [...u.searchParams.keys()])if(k.startsWith('utm_'))u.searchParams.delete(k);return (u.hostname+u.pathname.replace(/\/$/,'')+u.search).toLowerCase()}catch{return ''}}
function researchHTML(e){const r=RESEARCH[e.id];if(!r)return '';const refs=[...new Set(['alienint',...r.sections.flatMap(s=>s[2])])];return '<section class="research"><div class="eyebrow">SOURCED RESEARCH · REVIEWED OCT 5, 2026</div><p class="hint">References checked for attribution. Encounter claims remain unverified.</p>'+r.sections.map(([title,body,ids])=>'<h3>'+esc(title)+'</h3><p>'+esc(body)+'</p><div class="citations">'+ids.map(id=>'<a href="'+esc(REFERENCES[id].url)+'" target="_blank" rel="noopener">'+esc(REFERENCES[id].title)+' ↗</a>').join('')+'</div>').join('')+'<details class="source-list"><summary>Sources & review notes ('+refs.length+')</summary>'+refs.map(id=>{const s=REFERENCES[id];return '<div class="source-item"><a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.title)+' ↗</a><p class="hint">'+esc(s.type)+' · '+esc(s.access)+'</p><p>'+esc(s.note)+'</p></div>'}).join('')+'</details></section>'}
const labels={appearance:'Reported appearance',origin:'Claimed origin',behavior:'Reported behavior',encounters:'Notable encounter stories',related:'Related species',notes:'Research notes'};
function detail(id){const e=all().find(e=>e.id===id);if(!e)return;active=id;$('#detail-body').innerHTML=`<div class="detail-top"><div>${portrait(e)}</div><div><div class="eyebrow">FIELD RECORD / ${e.kind==='source'?'SOURCE COLLECTION':'MY ADDITIONS'}</div><h2>${esc(e.name)}</h2><p>${esc(e.summary)}</p><div class="eyebrow">${esc(e.status||'User-submitted / unverified')}</div></div></div>${researchHTML(e)}<details class="personal-notes"><summary>My research notes & additional details</summary><div>${Object.entries(labels).map(([key,label])=>`<h3>${label}</h3><p class="notes">${esc(e[key]||(key==='notes'?'Add your research, observations, and citations to this record.':'Not documented in this archive yet.'))}</p>`).join('')}</div></details>${e.source&&(!RESEARCH[e.id]||referenceKey(e.source)!==referenceKey(SOURCE))?`<a class="detail-source" href="${esc(safeURL(e.source))}" target="_blank" rel="noopener">Additional reference ↗</a>`:''}${e.kind==='source'?'<p class="hint">Starting summary and image: AlienINT, Morgan Carter. Additional research is attributed above. Illustrations are artistic interpretations.</p>':''}<div class="detail-actions"><button id="edit-entry">Edit entry</button>${e.kind==='custom'?'<button id="delete-entry">Delete entry</button>':''}</div>`;bindImages($('#detail'));$('#edit-entry').onclick=()=>{$('#detail').close();editor(id)};if($('#delete-entry'))$('#delete-entry').onclick=()=>{if(confirm(`Delete ${e.name} from your archive?`)&&persist({...state,entries:state.entries.filter(x=>x.id!==id),saved:state.saved.filter(x=>x!==id)})){$('#detail').close();render();toast('Entry deleted')}};if(!$('#detail').open)$('#detail').showModal()}
function editor(id=null){editing=id;$('#form').reset();$('#editor-title').textContent=id?'Edit species':'Add a species';if(id){const e=all().find(e=>e.id===id);for(const k of fields)if($('#form').elements[k])$('#form').elements[k].value=k==='image'&&e[k]?.startsWith('data:')?'':e[k]||''}$('#editor').showModal()}
for(const id of ['add','add-bottom'])$('#'+id).onclick=()=>editor();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
for(const [key,label]of Object.entries(labels)){if(key==='notes')continue;const l=document.createElement('label');l.textContent=label;const t=document.createElement('textarea');t.name=key;t.maxLength=3000;t.rows=2;l.append(t);$('#form').insertBefore(l,$('#form').elements.notes.parentElement)}
const statusLabel=document.createElement('label');statusLabel.textContent='Evidence status';const statusInput=document.createElement('input');statusInput.name='status';statusInput.maxLength=150;statusInput.placeholder='e.g. Folklore / unverified claims';statusLabel.append(statusInput);$('#form').insertBefore(statusLabel,$('#form').elements.notes.parentElement);
$('#form').onsubmit=async ev=>{ev.preventDefault();const button=$('#form button[type=submit]');button.disabled=true;try{const data=clean(Object.fromEntries(new FormData($('#form'))));data.name=data.name.trim();data.summary=data.summary.trim();if(!data.name||!data.summary)throw Error('Name and summary are required.');const file=$('#image-file').files[0];if(file){if(file.size>1024*1024)throw Error('Please choose an image smaller than 1 MB.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use PNG, JPEG, or WebP.');data.image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Image could not be read'));r.readAsDataURL(file)})}else if(editing&&!data.image){const old=all().find(x=>x.id===editing);if(old.image?.startsWith('data:'))data.image=old.image}let next={...state};if(editing&&seeds.some(x=>x.id===editing))next.overrides={...state.overrides,[editing]:data};else if(editing)next.entries=state.entries.map(e=>e.id===editing?{...e,...data}:e);else{if(state.entries.length>=200)throw Error('Maximum 200 custom entries.');next.entries=[...state.entries,{...data,id:'custom-'+Date.now()+'-'+Math.random().toString(36).slice(2),kind:'custom'}]}assertUniqueSpecies([...seeds.map(e=>({...e,...next.overrides[e.id]})),...next.entries]);if(persist(next)){$('#editor').close();filter='all';$('#search').value='';updateFilters();render();toast('Entry saved to your archive')}}catch(e){toast(e.message)}finally{button.disabled=false}};
function updateFilters(){document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))})}
$('#filters').onclick=ev=>{const b=ev.target.closest('[data-filter]');if(b){filter=b.dataset.filter;updateFilters();render()}};$('#search').oninput=render;$('#sort').onchange=render;$('#clear').onclick=()=>{filter='all';$('#search').value='';updateFilters();render()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='known-aliens-archive.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Archive exported')};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Backup must be smaller than 10 MB');const next=validate(JSON.parse(await file.text()));if(confirm('Replace your local additions, edits, and bookmarks with this backup?')&&persist(next)){render();toast('Archive restored')}}catch(e){toast('Import failed: '+e.message)}finally{ev.target.value=''}};
$('#about').onclick=()=>{$('#detail-body').innerHTML='<div class="eyebrow">ABOUT THE PROJECT</div><h2>A field guide to alien lore.</h2><p>Known Aliens is a personal research archive. Its twelve records combine AlienINT summaries and images with attributed research from archives, publishers, interviews, and historical scholarship. Source notes show which pages were directly reviewed and which were accessible only through indexed text.</p><p>Descriptions document stories and beliefs, not confirmed extraterrestrial life. Appearance, origin, behavior, encounters, and related-species fields can be expanded with your own referenced research.</p><p>Your edits and bookmarks are stored in this browser only. Export a backup before changing devices or clearing browser data. Images from AlienINT require an internet connection.</p><a class="detail-source" href="https://alienint.com/types-of-aliens/" target="_blank" rel="noopener">Visit AlienINT ↗</a>';$('#detail').showModal()};updateFilters();render();
